mapper.select:
SELECT id, order_no AS orderNo, user_id AS userId, total_amount AS totalAmount, status, create_time AS createTime, update_time AS updateTime FROM orders
id > #{lastId}
ORDER BY id LIMIT #{size}

SELECT id, order_id AS orderId, product_id AS productId, product_name AS productName, product_price AS productPrice, quantity, amount, create_time AS createTime, update_time AS updateTime FROM order_item WHERE order_id IN
#{orderId}
ORDER BY order_id, id

mapper.update:
UPDATE orders
SET status = #{toStatus},
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{fromStatus}
